package video

import (
	"bytes"
	"encoding/base64"
	"testing"
)

func TestEmbeddedFlatMP4sDecodeWithoutExternalDecoder(t *testing.T) {
	fixtures := map[string]string{
		"CAVLC": cavlcFlatMP4Base64,
		"CABAC": cabacFlatMP4Base64,
	}
	for name, encoded := range fixtures {
		t.Run(name, func(t *testing.T) {
			data, err := base64.StdEncoding.DecodeString(encoded)
			if err != nil {
				t.Fatal(err)
			}
			stream, err := OpenMP4(bytes.NewReader(data), int64(len(data)))
			if err != nil {
				t.Fatal(err)
			}
			if stream.Frames() != 12 {
				t.Fatalf("frames = %d, want 12", stream.Frames())
			}
			for index := 0; index < stream.Frames(); index++ {
				frame, decodeErr := stream.Decode(index)
				if decodeErr != nil {
					t.Fatalf("frame %d: %v", index, decodeErr)
				}
				var sum uint64
				for _, sample := range frame.Y {
					sum += uint64(sample)
				}
				if sum != 125952 {
					t.Fatalf("frame %d Y checksum = %d, want 125952", index, sum)
				}
			}
		})
	}
}

const cavlcFlatMP4Base64 = ""

const cabacFlatMP4Base64 = ""
